15 | export type InitResult = { created: string[]; kept: string[]; docsDir: string }
16 | 
17 | /**
18 |  * Sets a repository up for DocuGate: a docugate.json, and a first page if the
19 |  * docs folder has none. Never overwrites — running it twice is harmless, and
20 |  * running it in a repository that already has docs only adds what is missing.
21 |  */
22 | export function init(root: string, opts: { dir?: string; title?: string } = {}): InitResult {
23 |   const created: string[] = []
24 |   const kept: string[] = []
25 |   const existing = loadConfig(root)
26 |   const docsDir = (opts.dir ?? existing.docsDir).replace(/^\/|\/$/g, '') || 'docs'
27 |   const title = opts.title ?? basename(root)
28 | 
29 |   if (existing.found) {
30 |     kept.push(CONFIG_FILE)
31 |   } else {
32 |     const config = { docsDir, title }
33 |     writeFileSync(join(root, CONFIG_FILE), JSON.stringify(config, null, 2) + '\n')
34 |     created.push(CONFIG_FILE)
35 |   }
36 | 
37 |   const base = join(root, docsDir)
38 |   const hasMarkdown =
39 |     existsSync(base) && readdirSync(base, { recursive: true }).some((f) => /\.md$/i.test(String(f)))
40 | 
41 |   if (hasMarkdown) {
42 |     kept.push(`${docsDir}/`)
43 |   } else {
44 |     mkdirSync(base, { recursive: true })
45 |     writeFileSync(
46 |       join(base, 'index.md'),
47 |       `# ${title}\n\nWelcome. This page is the landing page of your DocuGate space.\n\n` +
48 |         `Every \`.md\` file in \`${docsDir}/\` becomes a page, and every folder becomes a\n` +
49 |         `section in the sidebar. The first \`# heading\` in a file is its title.\n`,
50 |     )
51 |     created.push(`${docsDir}/index.md`)
52 |   }
53 | 
54 |   return { created, kept, docsDir }
55 | }
56 | 
57 | // ---------------------------------------------------------------------------
58 | // Interactive setup flow
59 | // ---------------------------------------------------------------------------
60 | 
61 | export type Role = 'frontend' | 'backend' | 'both'
62 | 
63 | /** Minimal I/O surface so the flow can be driven by tests without a terminal. */
64 | export interface IO {
65 |   isTTY: boolean
66 |   ask(question: string, defaultAnswer: string): Promise<string>
67 |   print(line: string): void
68 | }
69 | 
70 | /** Injectable for tests: replaces the real getSpaces call. */
71 | export type GetSpacesFn = () => Promise<{ spaces: Space[] }>
72 | 
73 | /** Injectable for tests: replaces the real connectRepo call. */
74 | export type ConnectRepoFn = (spaceId: string, repo: string, docsDir: string) => Promise<void>
75 | 
76 | /** Injectable for tests: replaces the real getSession call. */
77 | export type GetSessionFn = () => Promise<{ user: { githubLogin: string } | null }>
78 | 
79 | /** Injectable for tests: replaces the real login call. */
80 | export type LoginFn = (baseUrl: string, opts?: LoginOptions) => Promise<{ token: string }>
81 | 
82 | /** Injectable for tests: replaces `git remote get-url origin`. Returns null if no remote. */
83 | export type GetRemoteFn = (root: string) => string | null
84 | 
85 | export interface InitFlowOptions {
86 |   dir?: string
87 |   title?: string
88 |   role?: Role
89 |   yes?: boolean
90 |   port?: number
91 |   io?: IO
92 |   runBob?: RunBob
93 |   getSessionFn?: GetSessionFn
94 |   getSpacesFn?: GetSpacesFn
95 |   connectFn?: ConnectRepoFn
96 |   loginFn?: LoginFn
97 |   getRemoteFn?: GetRemoteFn
98 |   /** Base URL for DocuGate (overrides DOCUGATE_URL env var). */
99 |   baseUrl?: string
100 | }
101 | 
102 | export interface InitFlowResult {
103 |   created: string[]
104 |   kept: string[]
105 |   docsDir: string
106 |   role: Role | undefined
107 |   tourResult?: TourInitResult
108 |   tourError?: string
109 |   installResult?: TourInstallResult
110 |   connectError?: string
111 | }
112 | 
113 | function makeDefaultIO(): IO {
114 |   const isTTY = Boolean(process.stdin.isTTY)
115 |   return {
116 |     isTTY,
117 |     ask(question, defaultAnswer) {
118 |       return new Promise((resolve) => {
119 |         const rl = createInterface({ input: process.stdin, output: process.stdout })
120 |         rl.question(`${question} `, (answer) => {
121 |           rl.close()
122 |           resolve(answer.trim() || defaultAnswer)
123 |         })
124 |       })
125 |     },
126 |     print(line) {
127 |       console.log(line)
128 |     },
129 |   }
130 | }
131 | 
132 | function saveRole(root: string, role: Role): void {
133 |   const path = join(root, CONFIG_FILE)
134 |   let existing: Record<string, unknown> = {}
135 |   if (existsSync(path)) {
136 |     try {
137 |       existing = JSON.parse(readFileSync(path, 'utf8')) as Record<string, unknown>
138 |     } catch {
139 |       // leave as empty object; will be overwritten with role added
140 |     }
141 |   }
142 |   existing.role = role
143 |   writeFileSync(path, JSON.stringify(existing, null, 2) + '\n')
144 | }
145 | 
146 | const VALID_ROLES = new Set<string>(['frontend', 'backend', 'both'])
147 | 
148 | function defaultGetRemote(root: string): string | null {
149 |   try {
150 |     const remote = execFileSync('git', ['remote', 'get-url', 'origin'], {
151 |       encoding: 'utf8',
152 |       cwd: root,
153 |       stdio: ['ignore', 'pipe', 'ignore'],
154 |     }).trim()
155 |     // Match HTTPS: https://github.com/owner/repo(.git)
156 |     // Match SSH:   git@github.com:owner/repo(.git)
157 |     const m = remote.match(/github\.com[:/]([^/]+\/[^/\s]+?)(?:\.git)?$/)
158 |     return m ? m[1] : null
159 |   } catch {
160 |     return null
161 |   }
162 | }
163 | 
164 | /**
165 |  * Runs the full interactive DocuGate setup wizard. Asks one short question,
166 |  * saves the result in docugate.json, conditionally runs tour init and tour
167 |  * install, and prints a summary.
168 |  */
169 | export async function initFlow(root: string, options: InitFlowOptions = {}): Promise<InitFlowResult> {
170 |   const io = options.io ?? makeDefaultIO()
171 |   const yes = options.yes ?? false
172 |   const port = options.port ?? DEFAULT_PORT
173 | 
174 |   // ── Step 1: base repo setup (docugate.json + docs/) ──────────────────────
175 |   const base = init(root, { dir: options.dir, title: options.title })
176 | 
177 |   // ── Step 2: determine role ────────────────────────────────────────────────
178 |   const loaded = loadConfig(root)
179 |   const savedRole = loaded.config.role
180 | 
181 |   let role: Role | undefined = savedRole ?? options.role
182 | 
183 |   if (!role) {
184 |     if (!io.isTTY) {
185 |       // CI / no terminal: write config without role and explain.
186 |       io.print(`  docugate.json written. Set the repository role with --role frontend|backend|both.`)
187 |       io.print(`  Run docugate login to connect this repository to a DocuGate space.`)
188 |       // Return early — no tour steps without a known role.
189 |       return { ...base, role: undefined }
190 |     }
191 | 
192 |     if (yes) {
193 |       // --yes with no --role: default to "both"
194 |       role = 'both'
195 |     } else {
196 |       // Interactive: ask once; re-prompt on invalid answer.
197 |       let answer = ''
198 |       while (!VALID_ROLES.has(answer)) {
199 |         answer = await io.ask(
200 |           'Is this repository the frontend, the backend, or both? [frontend/backend/both]',
201 |           'both',
202 |         )
203 |         if (!VALID_ROLES.has(answer)) {
204 |           io.print(`  Please answer frontend, backend, or both.`)
205 |         }
206 |       }
207 |       role = answer as Role
208 |     }
209 |   }
210 | 
211 |   if (!savedRole) {
212 |     saveRole(root, role)
213 |   }
214 | 
215 |   // ── Step 3: sign in and connect this repository ───────────────────────────
216 |   const BASE_URL = options.baseUrl ?? process.env.DOCUGATE_URL ?? 'https://www.trydocugate.site'
217 | 
218 |   let connectError: string | undefined
219 | 
220 |   // In CI (no TTY) skip sign-in entirely (hint already printed in the early-return branch above).
221 |   if (!io.isTTY) {
222 |     // nothing more — hint was already printed
223 |   } else {
224 |     // Lazily import real API functions only when not overridden by tests.
225 |     const realGetSession: GetSessionFn = async () => {
226 |       const { getSession } = await import('./api.js')
227 |       return getSession()
228 |     }
229 |     const realGetSpaces: GetSpacesFn = async () => {
230 |       const { getSpaces } = await import('./api.js')
231 |       return getSpaces()
232 |     }
233 |     const realConnectRepo: ConnectRepoFn = async (id, repo, dir) => {
234 |       const { connectRepo } = await import('./api.js')
235 |       return connectRepo(id, repo, dir)
236 |     }
237 |     const realLogin: LoginFn = login
238 | 
239 |     const getSessionFn = options.getSessionFn ?? realGetSession
240 |     const getSpacesFn = options.getSpacesFn ?? realGetSpaces
241 |     const connectFn = options.connectFn ?? realConnectRepo
242 |     const loginFn = options.loginFn ?? realLogin
243 |     const getRemoteFn = options.getRemoteFn ?? defaultGetRemote
244 | 
245 |     // ── 3a: ensure the user is signed in ─────────────────────────────────────
246 |     let signedIn = false
247 |     try {
248 |       // When getSessionFn is injected (tests), trust it directly.
249 |       // In production, only call it if there are saved credentials.
250 |       const creds = options.getSessionFn ? true : loadCredentials()
251 |       if (creds) {
252 |         const sess = await getSessionFn()
253 |         signedIn = sess.user !== null
254 |       }
255 |     } catch {
256 |       // can't reach server; treat as not signed in
257 |     }
258 | 
259 |     if (!signedIn) {
260 |       let doLogin = yes
261 |       if (!yes) {
262 |         const answer = await io.ask('Sign in to DocuGate now? [Y/n]', 'y')
263 |         doLogin = !/^n(o)?$/i.test(answer)
264 |       }
265 |       if (doLogin) {
266 |         try {
267 |           await loginFn(BASE_URL)
268 |           signedIn = true
269 |           io.print(`  Signed in to DocuGate.`)
270 |         } catch (err) {
271 |           connectError = `Sign-in failed: ${(err as Error).message}`
272 |           io.print(`  warning  ${connectError}`)
273 |         }
274 |       }
275 |     }
276 | 
277 |     // ── 3b: connect this repository to a space ────────────────────────────────
278 |     if (signedIn) {
279 |       // Read git remote.
280 |       const repoSlug = getRemoteFn(root)
281 | 
282 |       if (!repoSlug) {
283 |         io.print(`  This repository has no GitHub remote yet, so it can't be connected to a space.`)
284 |       } else {
285 |         // List spaces.
286 |         let spaces: Space[] = []
287 |         try {
288 |           const res = await getSpacesFn()
289 |           spaces = res.spaces
290 |         } catch (err) {
291 |           connectError = `Couldn't load spaces: ${(err as Error).message}`
292 |           io.print(`  warning  ${connectError}`)
293 |         }
294 | 
295 |         if (spaces.length === 0 && !connectError) {
296 |           io.print(`  No spaces found. Create one first: ${BASE_URL}/dashboard/new`)
297 |         } else if (spaces.length > 0) {
298 |           const { docsDir: repoDocsDir } = loadConfig(root)
299 | 
300 |           if (yes) {
301 |             // --yes: auto-connect only when there is exactly one space.
302 |             if (spaces.length === 1) {
303 |               try {
304 |                 await connectFn(spaces[0].id, repoSlug, repoDocsDir)
305 |                 io.print(`  Connected ${repoSlug} to space "${spaces[0].name}".`)
306 |               } catch (err) {
307 |                 connectError = (err as Error).message
308 |                 io.print(`  warning  ${connectError}`)
309 |               }
310 |             } else {
311 |               io.print(`  Multiple spaces found — run docugate init again without --yes to choose:`)
312 |               for (const s of spaces) io.print(`    ${s.owner}/${s.slug}  ${s.name}`)
313 |             }
314 |           } else {
315 |             // Interactive: list spaces and ask.
316 |             io.print(`  Your spaces:`)
317 |             for (let i = 0; i < spaces.length; i++) {
318 |               io.print(`    ${i + 1}. ${spaces[i].name}  (${spaces[i].owner}/${spaces[i].slug})`)
319 |             }
320 |             const answer = await io.ask(
321 |               `Connect ${repoSlug} to which space? [1-${spaces.length}/skip]`,
322 |               'skip',
323 |             )
324 |             const idx = parseInt(answer, 10) - 1
325 |             if (!isNaN(idx) && idx >= 0 && idx < spaces.length) {
326 |               try {
327 |                 await connectFn(spaces[idx].id, repoSlug, repoDocsDir)
328 |                 io.print(`  Connected ${repoSlug} to space "${spaces[idx].name}".`)
329 |               } catch (err) {
330 |                 connectError = (err as Error).message
331 |                 io.print(`  warning  ${connectError}`)
332 |               }
333 |             } else {
334 |               io.print(`  Skipped connecting to a space.`)
335 |             }
336 |           }
337 |         }
338 |       }
339 |     }
340 |   }
341 | 
342 |   // ── Step 4: tour steps (frontend / both only) ─────────────────────────────
343 |   let tourResult: TourInitResult | undefined
344 |   let tourError: string | undefined
345 |   let installResult: TourInstallResult | undefined
346 | 
347 |   if (role === 'frontend' || role === 'both') {
348 |     // Decide whether to run tour init.
349 |     let runTour = yes
350 |     if (!yes && io.isTTY) {
351 |       const answer = await io.ask('Write the tour with IBM Bob? (costs Bobcoins) [y/N]', 'n')
352 |       runTour = /^y(es)?$/i.test(answer)
353 |     }
354 | 
355 |     if (runTour) {
356 |       try {
357 |         tourResult = tourInit(root, { runBob: options.runBob })
358 |       } catch (error) {
359 |         // Bob missing or failed — describe what went wrong, then continue.
360 |         if (error instanceof BobKeyMissingError) {
361 |           tourError =
362 |             `Bob Shell needs an API key. Set BOB_API_KEY, then run docugate tour init.`
363 |         } else if (error instanceof BobMissingError) {
364 |           tourError =
365 |             `Bob Shell is not installed. Install it, sign in, then run docugate tour init.`
366 |         } else {
367 |           tourError = `Tour init failed: ${(error as Error).message}. Run docugate tour init to retry.`
368 |         }
369 |         io.print(`  warning  ${tourError}`)
370 |       }
371 |     }
372 | 
373 |     // tour install: ask in TTY unless --yes.
374 |     let runInstall = yes
375 |     if (!yes && io.isTTY) {
376 |       const answer = await io.ask('Add the pill loader to your app? [Y/n]', 'y')
377 |       runInstall = !/^n(o)?$/i.test(answer)
378 |     }
379 | 
380 |     if (runInstall) {
381 |       installResult = tourInstall(root, { port })
382 |       if (installResult.target === null) {
383 |         io.print(`  Paste this into your app's HTML during development:`)
384 |         io.print(`    ${pillSnippetLine(port)}`)
385 |       }
386 |     }
387 |   } else {
388 |     // backend
389 |     io.print(
390 |       `  backend role: skipping tour. The frontend repository's tour can point into this one.`,
391 |     )
392 |   }
393 | 
394 |   // ── Step 5: summary ───────────────────────────────────────────────────────
395 |   io.print(``)
396 |   for (const f of base.created) io.print(`  created  ${f}`)
397 |   for (const f of base.kept) io.print(`  kept     ${f}`)
398 |   if (!savedRole && role) io.print(`  saved    role: ${role} in ${CONFIG_FILE}`)
399 |   if (tourResult) {
400 |     for (const f of tourResult.setup) io.print(`  created  ${f}`)
401 |     for (const f of tourResult.added) io.print(`  added    ${f}`)
402 |     for (const f of tourResult.restored) io.print(`  kept     ${f} (Bob changed it; your version was put back)`)
403 |   }
404 |   if (installResult?.action === 'inserted') io.print(`  installed pill in ${installResult.target}`)
405 |   if (installResult?.action === 'already') io.print(`  pill already in ${installResult.target}`)
406 | 
407 |   io.print(``)
408 |   io.print(`Next: docugate tour serve`)
409 | 
410 |   return { ...base, role, tourResult, tourError, installResult, connectError }
411 | }
